CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY, google_id text UNIQUE NOT NULL, email text NOT NULL, name text NOT NULL, avatar text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS senders (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), name text NOT NULL, email text NOT NULL, smtp_secret text NOT NULL, hourly_limit integer NOT NULL CHECK(hourly_limit > 0), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS campaigns (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), sender_id uuid NOT NULL REFERENCES senders(id), subject text NOT NULL, body text NOT NULL, start_at timestamptz NOT NULL, delay_ms integer NOT NULL CHECK(delay_ms > 0), hourly_limit integer NOT NULL CHECK(hourly_limit > 0), idempotency_key text NOT NULL, request_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,idempotency_key));
CREATE TABLE IF NOT EXISTS emails (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), campaign_id uuid NOT NULL REFERENCES campaigns(id), sender_id uuid NOT NULL REFERENCES senders(id), recipient text NOT NULL, subject text NOT NULL, body text NOT NULL, scheduled_at timestamptz NOT NULL, status text NOT NULL DEFAULT 'scheduled' CHECK(status IN ('scheduled','sending','sent','failed','uncertain')), sent_at timestamptz, attempted_at timestamptz, message_id text, preview_url text, error text, version bigint NOT NULL DEFAULT 1, indexed_version bigint NOT NULL DEFAULT 0, queued boolean NOT NULL DEFAULT false, UNIQUE(campaign_id,recipient));
CREATE INDEX IF NOT EXISTS emails_user_status ON emails(user_id,status,scheduled_at);
CREATE INDEX IF NOT EXISTS emails_pending ON emails(scheduled_at) WHERE status='scheduled';
CREATE TABLE IF NOT EXISTS slack_connections (user_id uuid PRIMARY KEY REFERENCES users(id), team_name text NOT NULL, channel_name text NOT NULL, webhook_secret text NOT NULL, connected_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS notifications (id text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), text text NOT NULL, delivered_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
